import sys

MOD = 998244353
G = 3

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    S = data[1].strip()

    if S[0] == 'W' or S[-1] == 'B':
        print(0)
        return

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # For each W-event w (1..N), b_of_w[w] = number of B's before this W.
    L = [N + 1] * (N + 1)
    R = [0] * (N + 1)
    widx = 0
    bcnt = 0
    for ch in S:
        if ch == 'W':
            widx += 1
            if L[bcnt] == N + 1:
                L[bcnt] = widx
            R[bcnt] = widx
        else:
            bcnt += 1

    # q[b] = last non-final W-event with b B's before it, if it can create a particle.
    q = [-1] * (N + 1)
    active_pref = [0] * (N + 2)
    for b in range(N + 1):
        if L[b] <= R[b]:
            qa = R[b]
            if qa > N - 1:
                qa = N - 1
            if qa >= b and qa >= L[b]:
                q[b] = qa
        active_pref[b + 1] = active_pref[b] + (1 if q[b] != -1 else 0)

    if active_pref[N + 1] == 0:
        print(fact[N] % MOD)
        return

    next_active = [N + 1] * (N + 2)
    for b in range(N, -1, -1):
        if q[b] != -1:
            next_active[b] = b
        else:
            next_active[b] = next_active[b + 1]

    prev_active = [-1] * (N + 1)
    last = -1
    for b in range(N + 1):
        if q[b] != -1:
            last = b
        prev_active[b] = last

    A = [0] * (N + 1)   # A[b]
    Q = [0] * (N + 1)   # accumulated convolution values, indexed by W-event index

    max_log = (3 * N + 10).bit_length() + 1
    root_pw = [1] * (max_log + 1)
    iroot_pw = [1] * (max_log + 1)
    inv_pow2 = [1] * (max_log + 1)
    inv2 = (MOD + 1) // 2
    for k in range(1, max_log + 1):
        root_pw[k] = pow(G, (MOD - 1) >> k, MOD)
        iroot_pw[k] = pow(root_pw[k], MOD - 2, MOD)
        inv_pow2[k] = inv_pow2[k - 1] * inv2 % MOD

    rev_cache = {}

    def get_rev(n):
        rev = rev_cache.get(n)
        if rev is None:
            bits = n.bit_length() - 1
            rev = [0] * n
            for i in range(1, n):
                rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (bits - 1))
            rev_cache[n] = rev
        return rev

    def ntt(a, invert):
        n = len(a)
        rev = get_rev(n)
        for i in range(n):
            j = rev[i]
            if i < j:
                a[i], a[j] = a[j], a[i]

        length = 2
        stage = 1
        mod = MOD
        roots = iroot_pw if invert else root_pw
        while length <= n:
            wlen = roots[stage]
            half = length >> 1
            for i in range(0, n, length):
                w = 1
                end = i + half
                for j in range(i, end):
                    u = a[j]
                    v = a[j + half] * w % mod
                    x = u + v
                    if x >= mod:
                        x -= mod
                    y = u - v
                    if y < 0:
                        y += mod
                    a[j] = x
                    a[j + half] = y
                    w = w * wlen % mod
            length <<= 1
            stage += 1

        if invert:
            inv_n = inv_pow2[n.bit_length() - 1]
            for i in range(n):
                a[i] = a[i] * inv_n % mod

    def convolution(a, b):
        n = len(a)
        m = len(b)
        if n == 0 or m == 0:
            return []
        if n == 1:
            a0 = a[0]
            return [(a0 * x) % MOD for x in b]
        if m == 1:
            b0 = b[0]
            return [(x * b0) % MOD for x in a]

        if n * m <= 5000:
            if n > m:
                a, b = b, a
                n, m = m, n
            res = [0] * (n + m - 1)
            for i, ai in enumerate(a):
                if ai:
                    for j, bj in enumerate(b):
                        if bj:
                            res[i + j] = (res[i + j] + ai * bj) % MOD
            return res

        need = n + m - 1
        size = 1 << (need - 1).bit_length()
        fa = a + [0] * (size - n)
        fb = b + [0] * (size - m)
        ntt(fa, False)
        ntt(fb, False)
        for i in range(size):
            fa[i] = fa[i] * fb[i] % MOD
        del fb
        ntt(fa, True)
        return fa[:need]

    NAIVE_LIMIT = 12000

    def add_contrib(l, mid, first, last):
        # Add contributions of A[i] (l <= i <= mid) to Q[q[b]]
        # for active b in [first, last].
        nonzero = []
        for i in range(l, mid + 1):
            ai = A[i]
            if ai:
                nonzero.append((i, ai))
        if not nonzero:
            return

        # Sources with i > q[last] cannot contribute.
        qR = q[last]
        while nonzero and nonzero[-1][0] > qR:
            nonzero.pop()
        if not nonzero:
            return

        right_count = active_pref[last + 1] - active_pref[first]
        if right_count == 0:
            return

        if len(nonzero) <= 3 or right_count <= 3 or len(nonzero) * right_count <= NAIVE_LIMIT:
            for i, ai in nonzero:
                b = first
                while b <= last and q[b] < i:
                    b = next_active[b + 1]
                while b <= last:
                    qb = q[b]
                    Q[qb] = (Q[qb] + ai * fact[qb - i]) % MOD
                    b = next_active[b + 1]
            return

        qL = q[first]
        qR = q[last]
        Wq = qR - qL + 1

        l2 = nonzero[0][0]
        r2 = nonzero[-1][0]
        n = r2 - l2 + 1
        a = [A[i] for i in range(l2, r2 + 1)]

        offset = qL - l2
        m = n + Wq - 1
        start = offset - n + 1

        if start >= 0:
            b = fact[start:start + m]
            base = n - 1
        else:
            z = -start
            # trimmed leading zeros
            b = fact[0:qR - l2 + 1]
            base = n - 1 - z

        if not b:
            return

        conv = convolution(a, b)
        if not conv:
            return

        bidx = first
        while bidx <= last:
            qb = q[bidx]
            idx = base + (qb - qL)
            if 0 <= idx < len(conv):
                val = conv[idx]
                if val:
                    Q[qb] = (Q[qb] + val) % MOD
            bidx = next_active[bidx + 1]

    sys.setrecursionlimit(1_000_000)

    def cdq(l, r):
        if l > r or next_active[l] > r:
            return False
        if l == r:
            qa = q[l]
            if qa != -1:
                val = (fact[qa] + Q[qa]) % MOD
                av = (-val * invfact[qa - l]) % MOD
                A[l] = av
                return av != 0
            return False

        mid = (l + r) >> 1
        left_nonzero = cdq(l, mid)

        if left_nonzero:
            first = next_active[mid + 1]
            last = prev_active[r]
            if first <= last:
                add_contrib(l, mid, first, last)

        right_nonzero = cdq(mid + 1, r)
        return left_nonzero or right_nonzero

    cdq(0, N)

    ans = fact[N]
    for b in range(N + 1):
        if A[b]:
            ans = (ans + A[b] * fact[N - b]) % MOD

    print(ans % MOD)

