        if B == 0:
            # Red-only cycle: perimeter of a 2 x (R/2) rectangle.
            k = R // 2
            for c in range(k):
                append(f"R {OFF} {OFF + c}")
            for c in range(k - 1, -1, -1):
                append(f"R {OFF + 1} {OFF + c}")

        elif R == 0:
            # Blue-only cycle: rectangle in transformed coordinates.
            k = B // 2
            for v in range(k):
                append(f"B {OFF + v} {OFF - v}")
            for v in range(k - 1, -1, -1):
                append(f"B {OFF + 1 + v} {OFF + 1 - v}")

        else:
            if B & 1:
                # Blue path from (0,0) to (1,1), then red path back.
                k = (B - 1) // 2

                for v in range(k + 1):
                    append(f"B {OFF + v} {OFF - v}")
                for v in range(k, 0, -1):
                    append(f"B {OFF + 1 + v} {OFF + 1 - v}")

                m = R // 2
                for c in range(1, m + 1):
                    append(f"R {OFF + 1} {OFF + c}")
                for c in range(m, 0, -1):
                    append(f"R {OFF} {OFF + c}")

            else:
                # Blue path from (0,0) to (2,0), then red path back.
                k = B // 2 - 1

                for v in range(k + 2):
                    append(f"B {OFF + v} {OFF - v}")
                for v in range(k + 1, 1, -1):
                    append(f"B {OFF + 1 + v} {OFF + 1 - v}")

                m = R // 2
                for c in range(m):
                    append(f"R {OFF + 2} {OFF + c}")
                append(f"R {OFF + 1} {OFF + m - 1}")
                for c in range(m - 1, 0, -1):
                    append(f"R {OFF} {OFF + c}")

    sys.stdout.write("\n".join(out))

