from typing import List
from collections import deque

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)

        # If removing any element leaves fewer than k strings.
        if n == k:
            return [0] * n

        # Special case: for one string, its longest common prefix is itself.
        if k == 1:
            lengths = [len(w) for w in words]
            max_len = max(lengths)

            count_max = 0
            for length in lengths:
                if length == max_len:
                    count_max += 1

            second_max = 0
            if count_max == 1:
                for length in lengths:
                    if length != max_len and length > second_max:
                        second_max = length
            else:
                second_max = max_len

            ans = []
            for length in lengths:
                if length == max_len and count_max == 1:
                    ans.append(second_max)
                else:
                    ans.append(max_len)
            return ans

        # Sort strings; strings sharing a prefix form contiguous blocks.
        sorted_words = sorted((w, i) for i, w in enumerate(words))

        # lcp[i] = LCP of sorted_words[i] and sorted_words[i + 1]
        lcp = []
        prev = sorted_words[0][0]
        for i in range(1, n):
            cur = sorted_words[i][0]
            m = min(len(prev), len(cur))
            p = 0
            while p < m and prev[p] == cur[p]:
                p += 1
            lcp.append(p)
            prev = cur

        def sliding_min(arr: List[int], window: int) -> List[int]:
            """Minimum of every contiguous window of length `window` in arr."""
            if window <= 0 or window > len(arr):
                return []

            dq = deque()
            res = []

            for i, x in enumerate(arr):
                while dq and arr[dq[-1]] >= x:
                    dq.pop()
                dq.append(i)

                if dq[0] <= i - window:
                    dq.popleft()

                if i >= window - 1:
                    res.append(arr[dq[0]])

            return res

        # wk[l] = LCP of k consecutive sorted strings starting at l.
        # wk1[l] = LCP of k + 1 consecutive sorted strings starting at l.
        wk = sliding_min(lcp, k - 1)
        wk1 = sliding_min(lcp, k)

        # Prefix/suffix maxima of wk for windows not containing removed position.
        len_wk = len(wk)
        pref = [0] * len_wk
        for i, val in enumerate(wk):
            if i == 0:
                pref[i] = val
            else:
                pref[i] = pref[i - 1] if pref[i - 1] >= val else val

        suff = [0] * len_wk
        for i in range(len_wk - 1, -1, -1):
            val = wk[i]
            if i == len_wk - 1:
                suff[i] = val
            else:
                suff[i] = suff[i + 1] if suff[i + 1] >= val else val

        ans_sorted = [0] * n

        # Sliding maximum of wk1 over starts l such that [l, l + k] contains r.
        dq = deque()
        len_wk1 = len(wk1)

        for r in range(n):
            best = 0

            # Windows of size k that do not contain r.
            left = r - k
            if left >= 0:
                best = pref[left]

            right = r + 1
            if right < len_wk and suff[right] > best:
                best = suff[right]

            # Windows of size k + 1 that contain r.
            if r < len_wk1:
                val = wk1[r]
                while dq and wk1[dq[-1]] <= val:
                    dq.pop()
                dq.append(r)

            limit = r - k
            while dq and dq[0] < limit:
                dq.popleft()

            if dq and wk1[dq[0]] > best:
                best = wk1[dq[0]]

            ans_sorted[r] = best

        # Restore original order.
        result = [0] * n
        for pos, (_, original_index) in enumerate(sorted_words):
            result[original_index] = ans_sorted[pos]

        return result

