def check_positions(s: str, t: str, ch: str, mod: int) -> bool:
    if mod == 1:
        return True

    n = len(s)
    i = j = 0

    while True:
        while i < n and s[i] != ch:
            i += 1
        while j < n and t[j] != ch:
            j += 1

        if i == n or j == n:
            return i == n and j == n

        if i % mod != j % mod:
            return False

        i += 1
        j += 1


