class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 0:
            return n * (n + 1) // 2

        # bucket[x] contains all pairs whose smaller endpoint is x
        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[a].append((b, i))

        gains = [0] * m
        INF = n + 1

        # Smallest active y, its multiplicity, and its id if unique.
        min1 = INF
        min1_count = 0
        min1_id = -1

        # Second smallest distinct active y.
        min2 = INF

        base = 0

        # Sweep left endpoint from right to left.
        # Active pairs are those with smaller endpoint >= left.
        for left in range(n, 0, -1):
            for y, idx in buckets[left]:
                if y < min1:
                    min2 = min1
                    min1 = y
                    min1_count = 1
                    min1_id = idx
                elif y == min1:
                    min1_count += 1
                elif y < min2:
                    min2 = y

            if min1 == INF:
                base += INF - left
            else:
                base += min1 - left

                # Removing this unique minimum pair increases the valid
                # right-endpoint limit from min1 to min2 (or INF).
                if min1_count == 1:
                    gains[min1_id] += min2 - min1

        return base + max(gains)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1

        pat = [ord(ch) - 97 for ch in str2]

        # KMP prefix function
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pat[i] != pat[j]:
                j = pi[j - 1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j

        # KMP automaton transitions.
        # State is always in [0, m-1]; an occurrence is detected when
        # state == m-1 and the added character equals pat[m-1].
        trans = [[0] * 26 for _ in range(m)]
        for q in range(m):
            for c in range(26):
                if q > 0 and c != pat[q]:
                    trans[q][c] = trans[pi[q - 1]][c]
                elif c == pat[q]:
                    if q + 1 == m:
                        trans[q][c] = pi[m - 1]
                    else:
                        trans[q][c] = q + 1
                else:
                    trans[q][c] = 0

        bits = [1 << i for i in range(m)]
        full = (1 << m) - 1
        m1 = m - 1
        last = pat[-1]

        # For each state, mask of next states reachable by any character.
        # For the last state, also mask of next states reachable without
        # creating an occurrence (i.e. excluding the last character).
        all_pairs = []
        f_mask_last = 0
        for q in range(m):
            am = 0
            for nxt in trans[q]:
                am |= bits[nxt]
            all_pairs.append((am, bits[q]))

            if q == m1:
                fm = 0
                for c, nxt in enumerate(trans[q]):
                    if c != last:
                        fm |= bits[nxt]
                f_mask_last = fm

        f_pairs = all_pairs.copy()
        f_pairs[m1] = (f_mask_last, bits[m1])

        # Reverse masks for fast preimage when the next feasible set is a single bit.
        rev_all = [0] * m
        for q, (mask, bit) in enumerate(all_pairs):
            x = mask
            while x:
                lsb = x & -x
                r = lsb.bit_length() - 1
                rev_all[r] |= bit
                x -= lsb

        isT = [ch == 'T' for ch in str1]

        bit_before_t = bits[m1]
        bit_after_t = bits[pi[m1]]
        bit_last = bits[m1]
        clear_last = full ^ bit_last

        # feas[p] is a bitmask of KMP states from which positions p..L-1
        # can be completed while satisfying all remaining constraints.
        feas = [0] * (L + 1)
        feas[L] = full

        for p in range(L - 1, -1, -1):
            nb = feas[p + 1]
            if nb == 0:
                return ""

            # If this position finalizes a 'T' constraint, the state before
            # reading it must be m-1, and after reading it must be pi[m-1].
            if p >= m1 and isT[p - m1]:
                if nb & bit_after_t:
                    feas[p] = bit_before_t
                else:
                    return ""
                continue

            # For 'F' or no constraint, if every next state is feasible,
            # every current state is feasible because at least one allowed
            # character always exists.
            if nb == full:
                feas[p] = full
                continue

            # Fast path when only one next state is feasible.
            if (nb & (nb - 1)) == 0:
                b = rev_all[nb.bit_length() - 1]
                if p >= m1:  # this position finalizes an 'F' constraint
                    if f_mask_last & nb:
                        b |= bit_last
                    else:
                        b &= clear_last
            else:
                pairs = f_pairs if p >= m1 else all_pairs
                b = 0
                for mask, bit in pairs:
                    if mask & nb:
                        b |= bit

            if b == 0:
                return ""
            feas[p] = b

        if not (feas[0] & 1):
            return ""

        chars = [chr(97 + i) for i in range(26)]
        res = []
        q = 0

        # Greedily construct the lexicographically smallest valid string.
        for p in range(L):
            req = None
            if p >= m1:
                req = isT[p - m1]

            tq = trans[q]
            q_is_last = (q == m1)
            chosen = False

            for c in range(26):
                occ = q_is_last and (c == last)
                if req is not None and occ != req:
                    continue

                q2 = tq[c]
                if feas[p + 1] & bits[q2]:
                    res.append(chars[c])
                    q = q2
                    chosen = True
                    break

            if not chosen:
                return ""

        return ''.join(res)

