class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        circumference = 4 * s

        # Map each boundary point to its coordinate on the perimeter.
        # Order: (0,0) -> (s,0) -> (s,s) -> (0,s) -> (0,0)
        pos = []
        for x, y in points:
            if y == 0:
                pos.append(x)
            elif x == s:
                pos.append(s + y)
            elif y == s:
                pos.append(3 * s - x)
            else:  # x == 0
                pos.append(4 * s - y)

        pos.sort()
        n = len(pos)

        if k <= 1:
            return 0
        if k > n:
            return 0

        pos2 = pos + [p + circumference for p in pos]
        m = 2 * n
        steps = k - 1

        # For k >= 4, the answer is never larger than side.
        # Also, k selected points on a circle need k * d <= circumference.
        lo, hi = 0, min(side, circumference // k)

        def can(d: int) -> bool:
            if d == 0:
                return True
            if d * k > circumference:
                return False

            # nxt[i] = first index j > i with pos2[j] >= pos2[i] + d
            nxt = [m] * m
            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                target = pos2[i] + d
                while j < m and pos2[j] < target:
                    j += 1
                nxt[i] = j

            # Try every point as the first selected point in clockwise order.
            for i in range(n):
                idx = i
                end = i + n
                limit = pos2[i] + circumference - d

                for _ in range(steps):
                    idx = nxt[idx]
                    if idx >= end or pos2[idx] > limit:
                        break
                else:
                    return True

            return False

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        from bisect import bisect_left, bisect_right

        a, b, c = p.split('*')
        n = len(s)
        la, lb, lc = len(a), len(b), len(c)

        # Only "**" can match the empty substring.
        if la + lb + lc == 0:
            return 0

        # The literal parts must appear non-overlapping in order.
        if la + lb + lc > n:
            return -1

        def occurrences(pat: str):
            m = len(pat)
            if m == 0:
                return None
            if m > n:
                return []

            # KMP prefix function
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            # KMP search
            occ = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        occ.append(i - m + 1)
                        j = pi[j - 1]
            return occ

        occ_a = occurrences(a) if a else None
        if a and not occ_a:
            return -1

        occ_b = occurrences(b) if b else None
        if b and not occ_b:
            return -1

        occ_c = occurrences(c) if c else None
        if c and not occ_c:
            return -1

        INF = 10 ** 18
        ans = INF
        min_possible = la + lb + lc

        # If b is empty, its "start" can be any position 0..n.
        # Otherwise, it must be an actual occurrence of b.
        m_iter = occ_b if b else range(n + 1)

        for m in m_iter:
            # Choose the latest occurrence of a ending at or before m.
            xl = m - la
            if xl < 0:
                continue
            if xl > n:
                xl = n

            if a:
                idx = bisect_right(occ_a, xl) - 1
                if idx < 0:
                    continue
                left = occ_a[idx]
            else:
                left = xl  # la == 0

            # Choose the earliest occurrence of c starting at or after m + lb.
            xr = m + lb
            if xr > n:
                continue

            if c:
                idx = bisect_left(occ_c, xr)
                if idx == len(occ_c):
                    continue
                right = occ_c[idx]
            else:
                right = xr  # lc == 0

            length = right + lc - left
            if length < ans:
                ans = length
                if ans == min_possible:
                    return ans

        return -1 if ans == INF else ans

