MOD = 998244353


def calc_prime(p, arr, m):
    g = 0
    H = 0
    for a in arr:
        if a:
            g = gcd(g, a)
            H += a

    if g == 0:
        return 1

    if g > 1:
        b = [a // g for a in arr]
        H //= g
        base = pow(p, g, m)
    else:
        b = arr
        base = p % m

    H1 = H + 1

    powb = [1] * H1
    for i in range(1, H1):
        powb[i] = (powb[i - 1] * base) % m

    # dp0[h]: no zero has appeared yet, current height h
    # dp1[h]: zero has appeared at least once, current height h
    dp0 = powb.copy()
    dp0[0] = 0
    dp1 = [0] * H1
    dp1[0] = 1

    i = 0
    L = len(b)

    while i < L:
        a = b[i]

        if a == 0:
            z = 0
            while i < L and b[i] == 0:
                z += 1
                i += 1

            if z == 1:
                pb = powb
                d0 = dp0
                d1 = dp1
                for h in range(1, H1):
                    pbn = pb[h]
                    v = d0[h]
                    if v:
                        d0[h] = (v * pbn) % m
                    v = d1[h]
                    if v:
                        d1[h] = (v * pbn) % m
            else:
                base_z = pow(base, z, m)
                factor = base_z
                d0 = dp0
                d1 = dp1
                for h in range(1, H1):
                    v = d0[h]
                    if v:
                        d0[h] = (v * factor) % m
                    v = d1[h]
                    if v:
                        d1[h] = (v * factor) % m
                    factor = (factor * base_z) % m
            continue

        i += 1

        new0 = [0] * H1
        new1 = [0] * H1

        d0 = dp0
        d1 = dp1
        n0 = new0
        n1 = new1
        pb = powb

        # New height 0: only from old height a.
        s = d0[a] + d1[a]
        if s >= m:
            s -= m
        n1[0] = s

        end = H - a

        # New heights where only nh = h + a is possible.
        if end > 0:
            r_end = a if a < end + 1 else end + 1
            for nh in range(1, r_end):
                pbn = pb[nh]
                v = d0[nh + a]
                if v:
                    n0[nh] = (v * pbn) % m
                v = d1[nh + a]
                if v:
                    n1[nh] = (v * pbn) % m

        # New heights where both nh = h - a and nh = h + a are possible.
        if a <= end:
            for nh in range(a, end + 1):
                pbn = pb[nh]

                s0 = d0[nh - a] + d0[nh + a]
                if s0 >= m:
                    s0 -= m
                if s0:
                    n0[nh] = (s0 * pbn) % m

                s1 = d1[nh - a] + d1[nh + a]
                if s1 >= m:
                    s1 -= m
                if s1:
                    n1[nh] = (s1 * pbn) % m

        # New heights where only nh = h - a is possible.
        start = end + 1
        if start < a:
            start = a
        if start <= H:
            for nh in range(start, H1):
                pbn = pb[nh]
                v = d0[nh - a]
                if v:
                    n0[nh] = (v * pbn) % m
                v = d1[nh - a]
                if v:
                    n1[nh] = (v * pbn) % m

        dp0, dp1 = new0, new1

    return sum(dp1) % m


