class Solution:
    def countSubstrings(self, s: str) -> int:
        digits = [ord(c) - 48 for c in s]

        present = [False] * 10
        for d in digits:
            present[d] = True

        # Trivial endings:
        # 1: every number is divisible by 1
        # 2: every number ending in 2 is even
        # 5: every number ending in 5 is divisible by 5
        #
        # For 6, ending in 6 already guarantees divisibility by 2,
        # so only divisibility by 3 needs to be checked.
        #
        # For the remaining non-zero digits, maintain residues modulo
        # that digit for all substrings ending at the current position.
        mods = []
        if present[3] or present[6]:
            mods.append(3)
        if present[4]:
            mods.append(4)
        if present[7]:
            mods.append(7)
        if present[8]:
            mods.append(8)
        if present[9]:
            mods.append(9)

        counts = [[0] * m for m in range(10)]
        trans = [[None] * 10 for _ in range(10)]

        for m in mods:
            for d in range(10):
                trans[m][d] = [(r * 10 + d) % m for r in range(m)]

        ans = 0

        for i, d in enumerate(digits):
            # Update residue counts for all needed moduli.
            for m in mods:
                old = counts[m]
                new = [0] * m
                t = trans[m][d]

                for r, c in enumerate(old):
                    new[t[r]] += c

                # Substring consisting only of current digit.
                new[d % m] += 1
                counts[m] = new

            # Count valid substrings ending at position i.
            if d == 1 or d == 2 or d == 5:
                ans += i + 1
            elif d == 3 or d == 6:
                ans += counts[3][0]
            elif d == 4:
                ans += counts[4][0]
            elif d == 7:
                ans += counts[7][0]
            elif d == 8:
                ans += counts[8][0]
            elif d == 9:
                ans += counts[9][0]

        return ans

