    trans = []

    for mask in range(size):
        # dp[j] = LCS length of S[:j] and the processed string.
        # The mask stores positions where dp[j] - dp[j-1] == 1.
        dp = [0] * (N + 1)
        for j in range(1, N + 1):
            dp[j] = dp[j - 1] + ((mask >> (j - 1)) & 1)

        counts = {}

        for c in range(26):
            next_mask = 0
            prev = 0  # new_dp[j-1]

            for j in range(1, N + 1):
                if s_codes[j - 1] == c:
                    v = dp[j - 1] + 1
                    if dp[j] > v:
                        v = dp[j]
                    if prev > v:
                        v = prev
                else:
                    v = dp[j]
                    if prev > v:
                        v = prev

                if v > prev:
                    next_mask |= 1 << (j - 1)

                prev = v

            counts[next_mask] = counts.get(next_mask, 0) + 1

        trans.append(tuple(counts.items()))

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size

        for mask, val in enumerate(dp):
            if val == 0:
                continue
            for next_mask, cnt in trans[mask]:
                ndp[next_mask] += val * cnt

        dp = [x % MOD for x in ndp]

