            if t >= a:
                return a * b

            cnt = t * b
            c = a - t
            cnt += c * K - (t + 1 + a) * c // 2
            return cnt

        def sum_min(arr: List[int]) -> int:
            n = len(arr)

            prev = [-1] * n
            stack = []
            for i, x in enumerate(arr):
                while stack and arr[stack[-1]] >= x:
                    stack.pop()
                if stack:
                    prev[i] = stack[-1]
                stack.append(i)

            nxt = [n] * n
            stack = []
            for i in range(n - 1, -1, -1):
                x = arr[i]
                while stack and arr[stack[-1]] > x:
                    stack.pop()
                if stack:
                    nxt[i] = stack[-1]
                stack.append(i)

            total = 0
            for i, x in enumerate(arr):
                left = i - prev[i]
                right = nxt[i] - i
                total += x * count_pairs(left, right)

            return total

        return sum_min(nums) - sum_min([-x for x in nums])

