def pack_rows(rows, n, W):
    packs = []
    for row in rows:
        pack = 0
        shift = 0
        for val in row:
            if val:
                pack |= val << shift
            shift += W
        packs.append(pack)
    return packs


def mat_mul(A_rows, B_packs, n, mod, W, MASK, pack=True):
    C_rows = []
    C_packs = [] if pack else None
    Bp = B_packs
    rng = range(n)

    if pack:
        for Ai in A_rows:
            cp = 0
            for a, Bk in zip(Ai, Bp):
                if a:
                    cp += a * Bk

            row = [0] * n
            newpack = 0
            x = cp
            shift = 0
            for j in rng:
                if not x:
                    break
                val = x & MASK
                if val >= mod:
                    val %= mod
                if val:
                    row[j] = val
                    newpack |= val << shift
                x >>= W
                shift += W

            C_rows.append(row)
            C_packs.append(newpack)
    else:
        for Ai in A_rows:
            cp = 0
            for a, Bk in zip(Ai, Bp):
                if a:
                    cp += a * Bk

            row = [0] * n
            x = cp
            for j in rng:
                if not x:
                    break
                val = x & MASK
                if val >= mod:
                    val %= mod
                if val:
                    row[j] = val
                x >>= W

            C_rows.append(row)

    return C_rows, C_packs


def mat_pow(A, exp, n, mod, W, MASK):
    if exp == 0:
        one = 1 % mod
        return [[one if i == j else 0 for j in range(n)] for i in range(n)]

    base_rows = A
    base_packs = pack_rows(base_rows, n, W)
    res_rows = None
    e = exp

    while e:
        if e & 1:
            if res_rows is None:
                res_rows = base_rows
            else:
                res_rows, _ = mat_mul(res_rows, base_packs, n, mod, W, MASK, False)

        e >>= 1
        if e:
            base_rows, base_packs = mat_mul(base_rows, base_packs, n, mod, W, MASK, True)

    return res_rows


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, p = data[0], data[1]

    if p <= 1:
        line = " ".join(["0"] * n)
        sys.stdout.write("\n".join([line] * n))
        return

    if p == 2:
        v = str(n % 2)
        line = " ".join([v] * n)
        sys.stdout.write("\n".join([line] * n))
        return

    A = [data[2 + i * n: 2 + (i + 1) * n] for i in range(n)]

    max_sum = n * (p - 1) * (p - 1)
    W = max(1, max_sum.bit_length())
    MASK = (1 << W) - 1

    Ap = mat_pow(A, p, n, p, W, MASK)

    S = [[0] * n for _ in range(n)]
    K = 0

    for i in range(n):
        Ai = A[i]
        for j in range(n):
            if Ai[j] == 0:
                K += 1
                if i == j:
                    for r in range(n):
                        S[r][i] += A[r][i]
                    for c in range(n):
                        S[i][c] += Ai[c]
                elif p == 3:
                    S[i][j] += A[j][i]

    out = []
    if K & 1:
        for i in range(n):
            Aprow = Ap[i]
            Srow = S[i]
            vals = []
            for j in range(n):
                v = (Aprow[j] + Srow[j]) % p
                if v:
                    v = p - v
                vals.append(str(v))
            out.append(" ".join(vals))
    else:
        for i in range(n):
            Aprow = Ap[i]
            Srow = S[i]
            vals = [str((Aprow[j] + Srow[j]) % p) for j in range(n)]
            out.append(" ".join(vals))

    sys.stdout.write("\n".join(out))


