from collections import deque

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 1:
            return 1

        pref0 = [0] * (n + 1)  # cost to make prefix all '0'
        pref1 = [0] * (n + 1)  # cost to make prefix all '1'

        max_run = 1
        cur = 1

        for i in range(n):
            ch = s[i]
            pref0[i + 1] = pref0[i] + (1 if ch == '1' else 0)
            pref1[i + 1] = pref1[i] + (1 if ch == '0' else 0)

            if i > 0:
                if s[i] == s[i - 1]:
                    cur += 1
                else:
                    max_run = max(max_run, cur)
                    cur = 1

        max_run = max(max_run, cur)

        if max_run == 1 or numOps == 0:
            return max_run

        INF = 10 ** 9

        def can(k: int) -> bool:
            if k >= max_run:
                return True

            # dq0 stores indices j with increasing value:
            # dp1[j] - pref0[j], used when the last run is '0'
            dq0 = deque([(0, 0)])

            # dq1 stores indices j with increasing value:
            # dp0[j] - pref1[j], used when the last run is '1'
            dq1 = deque([(0, 0)])

            dp0 = dp1 = 0

            for i in range(1, n + 1):
                limit = i - k

                while dq0 and dq0[0][0] < limit:
                    dq0.popleft()
                while dq1 and dq1[0][0] < limit:
                    dq1.popleft()

                dp0 = pref0[i] + dq0[0][1] if dq0 else INF
                dp1 = pref1[i] + dq1[0][1] if dq1 else INF

                val0 = dp1 - pref0[i]
                while dq0 and dq0[-1][1] >= val0:
                    dq0.pop()
                dq0.append((i, val0))

                val1 = dp0 - pref1[i]
                while dq1 and dq1[-1][1] >= val1:
                    dq1.pop()
                dq1.append((i, val1))

            return min(dp0, dp1) <= numOps

        lo, hi = 1, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

import sys

def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    try:
        N = next(it)
    except StopIteration:
        return

    adj = [[] for _ in range(N)]
    for _ in range(N - 1):
        u = next(it) - 1
        v = next(it) - 1
        adj[u].append(v)
        adj[v].append(u)
    del it

    # Bucket vertices by their degree. Only degrees >= 2 can be used as y+1.
    buckets = {}
    get = buckets.get
    for i, nbrs in enumerate(adj):
        d = len(nbrs)
        if d >= 2:
            lst = get(d)
            if lst is None:
                buckets[d] = [i]
            else:
                lst.append(i)

    # Sweep thresholds D = y+1 in descending order.
    # counts[v] = number of neighbors of v whose degree is at least current D.
    counts = [0] * N
    max_count = 0
    max_g = 0
    target = N - 1

    for D in sorted(buckets, reverse=True):
        for u in buckets[D]:
            for w in adj[u]:
                nw = counts[w] + 1
                counts[w] = nw
                if nw > max_count:
                    max_count = nw

        val = D * max_count
        if val > max_g:
            max_g = val
            if max_g >= target:
                break

    # A snowflake always has at least 3 vertices under the constraints.
    if max_g < 2:
        max_g = 2
    if max_g > target:
        max_g = target

    print(N - max_g - 1)

