    solve()

class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0

        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        present = [x for x in cnt if x > 0]
        if len(set(present)) == 1:
            return 0

        ans = n - 1

        for k in range(1, 2 * n + 1):
            if k > n + ans:
                break

            dp0 = cnt[0]
            dp1 = cnt[0] - k
            if dp1 < 0:
                dp1 = -dp1

            for i in range(1, 26):
                ci = cnt[i]
                prev = cnt[i - 1]

                u1 = ci - k
                if u1 < 0:
                    u1 = -u1

                deficit = k - ci
                if deficit < 0:
                    deficit = 0

                save01 = prev if prev < deficit else deficit

                surplus = prev - k
                if surplus < 0:
                    surplus = 0
                save11 = surplus if surplus < deficit else deficit

                best_prev = dp0 if dp0 < dp1 else dp1
                ndp0 = best_prev + ci

                v0 = dp0 + u1 - save01
                v1 = dp1 + u1 - save11
                ndp1 = v0 if v0 < v1 else v1

                dp0, dp1 = ndp0, ndp1

            cost = dp0 if dp0 < dp1 else dp1
            if cost < ans:
                ans = cost
                if ans <= 1:
                    break

        return ans

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold

        # Values greater than threshold cannot have any edge, because
        # lcm(a, b) >= max(a, b).
        present = bytearray(T + 1)
        present_vals = []
        isolated = 0

        for x in nums:
            if x <= T:
                if not present[x]:
                    present[x] = 1
                    present_vals.append(x)
            else:
                isolated += 1

        if not present_vals:
            return isolated

        if len(present_vals) == 1:
            return isolated + 1

        # If 1 is present, every value <= threshold is directly connected to it.
        if present[1]:
            return isolated + 1

        parent = list(range(T + 1))
        size = [1] * (T + 1)

        # first[m] stores one present divisor of m already seen.
        first = [0] * (T + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        # For every possible common multiple m <= threshold, union all present
        # numbers that divide m. Two numbers have an edge iff they share such m.
        limit = T + 1
        for d in present_vals:
            for m in range(d, limit, d):
                f = first[m]
                if f == 0:
                    first[m] = d
                elif f != d:
                    union(d, f)

        roots = set()
        for x in present_vals:
            roots.add(find(x))

        return isolated + len(roots)
